// Bilan agrégé, sans donnée : par contrat, le nombre de sorties par statut ; par décision, le nombre par action. Défaut : un effet fait en
// simulation, un appel en erreur, ou un « pilote » sur un geste jamais automatique ou hors Signature et Entreprise.
const bilan = {}, actions = {};
let defauts = 0;
for (const { json: s } of $input.all()) {
  const c = typeof s.contrat === 'string' ? s.contrat : 'appel en erreur';
  bilan[c] = bilan[c] || {};
  const st = typeof s.statut === 'string' ? s.statut : 'erreur';
  bilan[c][st] = (bilan[c][st] || 0) + 1;
  if (!s.contrat || st === 'erreur' || (s.simulation === true && Array.isArray(s.effets_faits) && s.effets_faits.length)) defauts++;
